import * as THREE from 'three';
import {createHandlingRig} from './forklift-rig.js';
import {logisticsFrame} from './logistics-motion.js';
import {docks} from '../layout/site-layout.js';
import {routePose,turnLength} from './handling-motion.js';

export function bindLogistics(scene,built,{onRoot=()=>{}}={}){
 const parent=scene;scene=new THREE.Group();scene.name='dock-operation';parent.add(scene);
 const boxGeometry=new THREE.BoxGeometry(1,1,1),wheelGeometry=new THREE.CylinderGeometry(.48,.48,.28,24),materials=new Map();
 const mat=color=>{if(!materials.has(color))materials.set(color,new THREE.MeshStandardMaterial({color,roughness:.8}));return materials.get(color);};
 function box(parent,x,y,z,w,h,d,color){const m=new THREE.Mesh(boxGeometry,mat(color));m.position.set(x,y,z);m.scale.set(w,h,d);m.castShadow=m.receiveShadow=true;parent.add(m);return m;}
 function makeTruck(){const root=new THREE.Group();scene.add(root);box(root,1,.70,0,7.5,.32,2.15,'#3d4d43');box(root,-.15,.855,0,5.1,.08,2.3,'#a0a58c');const roof=box(root,-.15,2.94,0,5.2,.12,2.4,'#607f8f');box(root,-.15,1.9,-1.15,5.1,2.05,.06,'#527b8f');for(const x of [-2.7,2.4])box(root,x,1.9,0,.06,2.05,2.3,'#527b8f');box(root,3.6,1.77,0,2.1,1.7,2.24,'#dce0cb');box(root,4.66,2.1,0,.03,.65,1.94,'#3c6265');const shutter=box(root,-.15,1.9,1.15,5.1,2.05,.06,'#5a8294'),wheels=[],chocks=new THREE.Group();root.add(chocks);
  for(let i=0;i<4;i++){const pivot=new THREE.Group(),spin=new THREE.Group(),tire=new THREE.Mesh(wheelGeometry,mat('#293831'));pivot.position.set(i<2?0:3.7,.48,i%2?.99:-.99);root.add(pivot);pivot.add(spin);spin.add(tire);tire.rotation.x=Math.PI/2;tire.castShadow=true;for(const a of [0,Math.PI/2]){const m=box(spin,0,0,i%2?.145:-.145,.07,.65,.012,'#a4b39d');m.rotation.z=a;}wheels.push({pivot,spin});}
  for(const z of [-.99,.99])for(const x of [-.57,.57])box(chocks,x,.08,z,.2,.16,.34,'#c4a548');
  return {root,roof,shutter,wheels,chocks};
 }
 function makeBuffer(x){const group=new THREE.Group();group.position.set(x,.05,36.8);scene.add(group);box(group,-.99,1.5,-.3,.08,3,2.8,'#6b8176');box(group,0,1.5,1.05,2,3,.08,'#80958a');box(group,0,3.05,-.3,2.1,.1,2.9,'#627f7a');const door=box(group,1,1.5,-.3,.07,3,2.8,'#668682'),rollers=[];const geometry=new THREE.CylinderGeometry(.04,.04,1.4,10);for(let z=-1.1;z<=.5;z+=.16){const pivot=new THREE.Group(),roller=new THREE.Mesh(geometry,mat('#bcc8c0'));pivot.position.set(0,-.04,z);roller.rotation.z=Math.PI/2;roller.castShadow=true;pivot.add(roller);group.add(pivot);rollers.push(pivot);}return {group,door,rollers};}
 const trucks=[makeTruck(),makeTruck()],loaders=[createHandlingRig(scene),createHandlingRig(scene)],buffers=[makeBuffer(docks.receiving.x-.8),makeBuffer(docks.dispatch.x-.8)];loaders.forEach(r=>r.platform.visible=false);built.referenceVehicles.slice(0,2).forEach(r=>r.visible=false);let current=null;
 const cargo=loaders.map(r=>Array.from({length:2},()=>{const mesh=r.pallet.clone(true);scene.add(mesh);onRoot(mesh);return mesh;}));trucks.forEach(r=>onRoot(r.root));loaders.forEach(r=>{onRoot(r.root);onRoot(r.pallet);});buffers.forEach(r=>onRoot(r.group));
 for(const dock of Object.values(docks)){box(scene,dock.x+1.4,.04,37.3,11,.02,4.4,'#aeb4a1');for(const z of [-.99,.99])for(const x of [-.57,.57])box(scene,dock.x+x,.052,dock.y+z,.26,.004,.4,'#34483c');const points=[];for(let i=0;i<=100;i++){const p=routePose((turnLength+1.85)*i/100);points.push(new THREE.Vector3(p.x+dock.x+1.4-11.2,.073,p.z+20.8));}const guide=new THREE.Line(new THREE.BufferGeometry().setFromPoints(points),new THREE.LineDashedMaterial({color:'#d5b66a',dashSize:.3,gapSize:.22}));guide.computeLineDistances();scene.add(guide);}
 function apply(source,time=source.time){current=logisticsFrame(source,time);current.trucks.forEach((t,i)=>{const r=trucks[i];r.root.visible=t.visible;r.root.position.set(t.pose.x,.055,t.pose.z);r.root.rotation.y=-t.pose.yaw;const h=Math.max(.02,2.05*(1-t.door));r.shutter.scale.y=h;r.shutter.position.y=2.925-h/2;r.chocks.visible=t.phase==='docked';r.chocks.position.y=0;for(const chock of r.chocks.children){chock.userData.baseZ??=chock.position.z;chock.position.z=chock.userData.baseZ+Math.sign(chock.userData.baseZ)*(1-t.restraint)*.65;}r.wheels.forEach((w,j)=>{w.pivot.rotation.y=-t.steering[j];w.spin.rotation.z=-t.roll[j]/.48;});});
  current.loaders.forEach((f,i)=>{const r=loaders[i];r.apply(f,f.load.owner==='truck'?trucks[i].root:null);r.pallet.visible=f.visibleLoad&&(f.load.owner!=='truck'||current.trucks[i].visible);r.root.userData.id='SUPPORT-'+f.kind;r.pallet.userData.id=f.load.id;r.pallet.name=f.load.id;for(let slot=0;slot<2;slot++){const mesh=cargo[i][slot],item=f.cargoes?.[slot];mesh.visible=!!item&&!item.active&&item.visible;if(!mesh.visible)continue;mesh.name=item.id;if(item.owner==='truck'){if(mesh.parent!==trucks[i].root)trucks[i].root.add(mesh);mesh.position.set(item.truckLocalX,.895,.55);mesh.rotation.set(0,Math.PI/2,0);}else{if(mesh.parent!==scene)scene.add(mesh);mesh.position.set(item.x,.05+item.bottom,item.z);mesh.rotation.set(0,-item.yaw,0);}}for(const roller of buffers[i].rollers)roller.rotation.x=(i?1:-1)*((current.trucks[i].round||0)*2+(f.belt||0))*.8/.04;const door=buffers[i].door,h=Math.max(.02,3*(1-f.shutter));door.scale.y=h;door.position.y=3-h/2;});
 }
 return {apply,root:scene,get frame(){return current;},trucks,loaders,buffers,state:()=>current};
}
